CREATE TABLE morrow.talent_pools(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES morrow.organizations,name text NOT NULL,description text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(org_id,name),UNIQUE(org_id,id));
CREATE TABLE morrow.talent_pool_memberships(org_id uuid NOT NULL,pool_id uuid NOT NULL,candidate_id uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(pool_id,candidate_id),FOREIGN KEY(org_id,pool_id) REFERENCES morrow.talent_pools(org_id,id),FOREIGN KEY(org_id,candidate_id) REFERENCES morrow.candidates(org_id,id));
